#!/usr/bin/env python3
"""Generates the enumerated parts of rs/PROOF.bend.

PROOF.bend keeps its hand-written lemmas; the parts between
'# BEGIN GENERATED by gen/proof.py: <name>' and '# END GENERATED: <name>'
are rewritten by this script:

  bits    lemmas proved by splitting words into their 32 bits (the low bits
          of a symbol are read, the others masked away);
  dist8   in GF(8): (x + y) k = x k + y k for each constant k the
          syndromes and the encoder of Rs.small8 multiply by, by trying
          the 64 pairs of low three bits;
  lin8    Horner's rule at each root of Rs.small8 is linear: the
          syndrome of a sum of words, by induction on the words;
  basis8  the syndromes of the codewords of Rs.small8's basis messages
          (one symbol a in one place), by trying the 8 values of a;
  small4  Rs.small4's laws, by trying every message symbol, error
          position and error value;
  inv     a a^-1 = 1 in GF(8) and GF(16), by trying every element.

The tried values are computed in defs of their own whose statements have
no unknown bits: the proof kernel has a step budget per def, and computes
literals far faster than words with unknown bits.

Usage: python3 gen/proof.py   (from rs/)
"""
import os, re

HERE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def word(bits):
    """A U32 pattern or term from a list of 32 bit expressions."""
    inner = "WNil{}"
    for b in reversed(bits):
        inner = "WCon{%s, %s}" % (b, inner)
    return "U32{%s}" % inner


def sym(prefix):
    return ["%s%d" % (prefix, i) for i in range(32)]


def low(prefix, value, nlow):
    """bits: the low nlow fixed to value, the rest symbolic"""
    out = []
    for i in range(32):
        if i < nlow:
            out.append("True{}" if (value >> i) & 1 else "False{}")
        else:
            out.append("%s%d" % (prefix, i))
    return out


F8 = "C.Rs.gf8()"
F4 = "C.Rs.gf4()"


def gen_bits():
    out = []
    a, b = word(sym("a")), word(sym("b"))
    for name, field in (("8", F8), ("4", F4)):
        out.append("# elt (elt u + v) = elt (u + v)")
        out.append("def rsp.e1_%s(u: U32, v: U32) -> {M.Gfm.elt(%s, U32.xor(M.Gfm.elt(%s, u), v)) == M.Gfm.elt(%s, U32.xor(u, v)) : U32}:" % (name, field, field, field))
        out.append("  match u v:\n    case %s %s:\n      {==}\n" % (a, b))
        out.append("# elt (u + elt v) = elt (u + v)")
        out.append("def rsp.e2_%s(u: U32, v: U32) -> {M.Gfm.elt(%s, U32.xor(u, M.Gfm.elt(%s, v))) == M.Gfm.elt(%s, U32.xor(u, v)) : U32}:" % (name, field, field, field))
        out.append("  match u v:\n    case %s %s:\n      {==}\n" % (a, b))
        out.append("def rsp.eid_%s(u: U32) -> {M.Gfm.elt(%s, M.Gfm.elt(%s, u)) == M.Gfm.elt(%s, u) : U32}:" % (name, field, field, field))
        out.append("  match u:\n    case %s:\n      {==}\n" % a)
        out.append("# 0 + y = elt y")
        out.append("def rsp.a0_%s(y: U32) -> {M.Gfm.add(%s, 0, y) == M.Gfm.elt(%s, y) : U32}:" % (name, field, field))
        out.append("  match y:\n    case %s:\n      {==}\n" % b)
        out.append("# a product is an element")
        out.append("def rsp.emul_%s(u: U32, v: U32) -> {M.Gfm.elt(%s, M.Gfm.mul(%s, u, v)) == M.Gfm.mul(%s, u, v) : U32}:" % (name, field, field, field))
        n = 3 if name == "8" else 2
        out.append("  match u v:")
        for x in range(1 << n):
            for y in range(1 << n):
                out.append("    case %s %s:\n      {==}" % (word(low("a", x, n)), word(low("b", y, n))))
        out.append("")
    f16 = "M.Gfm.gf16()"
    out.append("def rsp.eid_16(u: U32) -> {M.Gfm.elt(%s, M.Gfm.elt(%s, u)) == M.Gfm.elt(%s, u) : U32}:" % (f16, f16, f16))
    out.append("  match u:\n    case %s:\n      {==}\n" % word(sym("a")))
    return "\n".join(out)


def gen_dist8():
    out = []
    for k in (1, 2, 3, 4, 6):
        out.append("def rsp.dist8_%d(x: U32, y: U32) -> {M.Gfm.mul(%s, M.Gfm.add(%s, x, y), %d) == M.Gfm.add(%s, M.Gfm.mul(%s, x, %d), M.Gfm.mul(%s, y, %d)) : U32}:" % (k, F8, F8, k, F8, F8, k, F8, k))
        out.append("  match x y:")
        for x in range(8):
            for y in range(8):
                out.append("    case %s %s:\n      {==}" % (word(low("a", x, 3)), word(low("b", y, 3))))
        out.append("")
    return "\n".join(out)


def gen_lin8():
    out = []
    A8 = "M.Gfm.add(%s, " % F8
    M8 = "M.Gfm.mul(%s, " % F8
    LEN = "List.length(&2, U32, "
    ADD = "P.RsPoly.add(%s, " % F8
    SO = "Sy.rs.syn.one("
    for k in (2, 4, 3, 6):
        out.append("# the Horner step at %d: (a1 + a2) %d + (x + y) = (a1 %d + x) + (a2 %d + y)" % (k, k, k, k))
        out.append("def rsp.hacc_%d(+a1: U32, +a2: U32, +x: U32, +y: U32) -> {%s%s%sa1, a2), %d), %sx, y)) == %s%s%sa1, %d), x), %s%sa2, %d), y)) : U32}:" % (k, A8, M8, A8, k, A8, A8, A8, M8, k, A8, M8, k))
        out.append("  %%Equal.sym(U32, %s%sa1, a2), %d), %s%sa1, %d), %sa2, %d)), rsp.dist8_%d(a1, a2)) : {%s_, %sx, y)) == %s%s%sa1, %d), x), %s%sa2, %d), y)) : U32}" % (M8, A8, k, A8, M8, k, M8, k, k, A8, A8, A8, A8, M8, k, A8, M8, k))
        out.append("  rsp.add8_sh(%sa1, %d), %sa2, %d), x, y)\n" % (M8, k, M8, k))
        goal = "{%s%s%s, w2), %s, %d, %sa1, a2)) == %s%sw1, %s, %d, a1), %sw2, %s, %d, a2)) : U32}" % (SO, ADD, "w1", F8, k, A8, A8, SO, F8, k, SO, F8, k)
        out.append("def rsp.hlin_%d(w1: List<&2, U32>, w2: List<&2, U32>, +a1: U32, +a2: U32, +same: {%sw1) == %sw2) : Nat}) -> %s:" % (k, LEN, LEN, goal))
        out.append("  match w1 w2:")
        out.append("    case Nil{} Nil{}:\n      {==}")
        g2 = goal.replace("w1", "Nil{}").replace("w2", "Con{y, t}")
        out.append("    case Nil{} Con{y, t}:\n      Empty.absurd(%s, rsp.succ_zero(%st), Equal.sym(Nat, 0n, 1n+%st), same)))" % (g2, LEN, LEN))
        g3 = goal.replace("w1", "Con{x, s}").replace("w2", "Nil{}")
        out.append("    case Con{x, s} Nil{}:\n      Empty.absurd(%s, rsp.succ_zero(%ss), same))" % (g3, LEN))
        ac1 = "%s%sa1, %d), x)" % (A8, M8, k)
        ac2 = "%s%sa2, %d), y)" % (A8, M8, k)
        out.append("    case Con{+x, +s} Con{+y, +t}:")
        out.append("      %%Equal.sym(U32, %s%s%sa1, a2), %d), %sx, y)), %s%s, %s), rsp.hacc_%d(a1, a2, x, y)) : {%s%ss, t), %s, %d, _) == %s%ss, %s, %d, %s), %st, %s, %d, %s)) : U32}" % (A8, M8, A8, k, A8, A8, ac1, ac2, k, SO, ADD, F8, k, A8, SO, F8, k, ac1, SO, F8, k, ac2))
        out.append("      rsp.hlin_%d(s, t, %s, %s, rsp.succ_inj(%ss), %st), same))\n" % (k, ac1, ac2, LEN, LEN))
    return "\n".join(out)


def gen_basis8():
    """The syndromes of the codewords of one-symbol messages: the message
    is masked (rsp.cwmask), its symbol split into bits, and each of the 8
    values computed in a def of its own whose statement has no unknown
    bits (the kernel computes literals quickly)."""
    out = []
    sm, z = "C.Rs.small8()", "[0, 0, 0, 0]"
    shapes = [  # (name, length, place)
        ("a", 1, 0), ("ab0", 2, 0), ("ab1", 2, 1), ("abc0", 3, 0), ("abc1", 3, 1), ("abc2", 3, 2),
    ]
    hs = ", ".join("+a%d: Bool" % i for i in range(3, 32))
    hargs = ", ".join("a%d" % i for i in range(3, 32))
    L = "List<&2, U32>"
    for name, length, place in shapes:
        def msg(x):
            return "[%s]" % ", ".join(x if i == place else "0" for i in range(length))
        for v in range(8):
            out.append("def rsp.lm8_%s_%d(%s) -> {%s == E.Rs.mask(%s, %s) : %s}:\n  {==}\n" % (name, v, hs, msg(str(v)), sm, msg(word(low("a", v, 3))), L))
            out.append("def rsp.bl_%s_%d() -> {Sy.Rs.syndromes(%s, E.Rs.codeword(%s, %s)) == %s : %s}:\n  {==}\n" % (name, v, sm, sm, msg(str(v)), z, L))
        out.append("def rsp.bc_%s(x: U32) -> {Sy.Rs.syndromes(%s, E.Rs.codeword(%s, E.Rs.mask(%s, %s))) == %s : %s}:" % (name, sm, sm, sm, msg("x"), z, L))
        out.append("  match x:")
        for v in range(8):
            out.append("    case %s:" % word(low("a", v, 3)))
            out.append("      %%rsp.lm8_%s_%d(%s) : {Sy.Rs.syndromes(%s, E.Rs.codeword(%s, _)) == %s : %s}" % (name, v, hargs, sm, sm, z, L))
            out.append("      rsp.bl_%s_%d()" % (name, v))
        out.append("")
        out.append("def rsp.basis_%s(+x: U32) -> {Sy.Rs.syndromes(%s, E.Rs.codeword(%s, %s)) == %s : %s}:" % (name, sm, sm, msg("x"), z, L))
        out.append("  %%rsp.cwmask(%s) : {Sy.Rs.syndromes(%s, _) == %s : %s}" % (msg("x"), sm, z, L))
        out.append("  rsp.bc_%s(x)\n" % name)
    return "\n".join(out)


def gf4mul(a, b):
    r = 0
    for i in range(2):
        if (b >> i) & 1:
            r ^= a << i
    for i in (3, 2):
        if (r >> i) & 1:
            r ^= 7 << (i - 2)
    return r


def small4_codeword(x):
    """[x] encoded by Rs.small4: g(X) = (X + 2)(X + 3) = X^2 + X + 1"""
    g = [1, 1]  # g_1, g_0 below the leading 1
    reg = [0, 0]
    fb = x ^ reg[0]
    reg = [reg[1] ^ gf4mul(fb, g[0]), gf4mul(fb, g[1])]
    return [x] + reg


def gen_small4():
    """Rs.small4's laws. Each law first masks the message (rsp.cwmask4)
    and the change (rsp.decv4); then the message symbol, the position and
    the change's value are tried, the unknown high bits rewritten away
    (rsp.lm4_X, rsp.l4_X), so that each decode is computed on literals in
    a def of its own (the kernel's per-def fuel)."""
    out = []
    sm, f = "C.Rs.small4()", F4
    R = "Result<&2, &2, E.RsError, List<&2, U32>>"
    L = "List<&2, U32>"
    hs = ", ".join("+c%d: Bool" % i for i in range(2, 32))
    cargs = ", ".join("c%d" % i for i in range(2, 32))
    bargs = ", ".join("b%d" % i for i in range(2, 32))

    def pa(x):
        return word(low("c", x, 2))

    def pb(x):
        return word(low("b", x, 2))
    out.append("# a change past the word's end changes nothing")
    out.append("def rsp.inj3(+a: U32, +b: U32, +c: U32, k: Nat, v: U32) -> {[a, b, c] == D.Rs.inject([a, b, c], 3n+k, v) : %s}:\n  {==}\n" % L)
    for x in range(4):
        cwl = small4_codeword(x)
        out.append("def rsp.cw4_%d() -> {[%s] == E.Rs.codeword(%s, [%d]) : %s}:\n  {==}\n" % (x, ", ".join(map(str, cwl)), sm, x, L))
        out.append("def rsp.s4e_%d_far() -> {D.Rs.decode(%s, [%s], Nil{}) == Done{E.Rs.mask(%s, [%d])} : %s}:\n  {==}\n" % (x, sm, ", ".join(map(str, cwl)), sm, x, R))
    for x in range(4):
        out.append("def rsp.lm4_%d(%s) -> {[%d] == E.Rs.mask(%s, [%s]) : %s}:\n  {==}\n" % (x, hs, x, sm, pa(x), L))
        out.append("def rsp.l4_%d(%s) -> {%d == M.Gfm.elt(%s, %s) : U32}:\n  {==}\n" % (x, hs, x, f, pa(x)))
    # syndromes
    for x in range(4):
        out.append("def rsp.s4sy_%d() -> {Sy.Rs.syndromes(%s, E.Rs.codeword(%s, [%d])) == [0, 0] : %s}:\n  {==}\n" % (x, sm, sm, x, L))
    out.append("def rsp.s4sy_c(a: U32) -> {Sy.Rs.syndromes(%s, E.Rs.codeword(%s, E.Rs.mask(%s, [a]))) == [0, 0] : %s}:\n  match a:" % (sm, sm, sm, L))
    for x in range(4):
        out.append("    case %s:\n      %%rsp.lm4_%d(%s) : {Sy.Rs.syndromes(%s, E.Rs.codeword(%s, _)) == [0, 0] : %s}\n      rsp.s4sy_%d()" % (pa(x), x, cargs, sm, sm, L, x))
    out.append("")
    out.append("def Laws.small4_syndromes(a):\n  %%rsp.cwmask4([a]) : {Sy.Rs.syndromes(%s, _) == [0, 0] : %s}\n  rsp.s4sy_c(a)\n" % (sm, L))
    # roundtrip
    for x in range(4):
        out.append("def rsp.s4rt_%d() -> {D.Rs.decode(%s, E.Rs.codeword(%s, [%d]), Nil{}) == Done{E.Rs.mask(%s, [%d])} : %s}:\n  {==}\n" % (x, sm, sm, x, sm, x, R))
    out.append("def rsp.s4rt_c(a: U32) -> {D.Rs.decode(%s, E.Rs.codeword(%s, E.Rs.mask(%s, [a])), Nil{}) == Done{E.Rs.mask(%s, [a])} : %s}:\n  match a:" % (sm, sm, sm, sm, R))
    for x in range(4):
        out.append("    case %s:\n      %%rsp.lm4_%d(%s) : {D.Rs.decode(%s, E.Rs.codeword(%s, _), Nil{}) == Done{E.Rs.mask(%s, [%d])} : %s}\n      rsp.s4rt_%d()" % (pa(x), x, cargs, sm, sm, sm, x, R, x))
    out.append("")
    out.append("def Laws.small4_roundtrip(a):\n  %%rsp.cwmask4([a]) : {D.Rs.decode(%s, _, Nil{}) == Done{E.Rs.mask(%s, [a])} : %s}\n  rsp.s4rt_c(a)\n" % (sm, sm, R))
    # one error, one erasure
    for kind, eras in (("e", lambda i: "Nil{}"), ("r", lambda i: "[%s]" % i)):
        for x in range(4):
            cw = "E.Rs.codeword(%s, [%d])" % (sm, x)
            rhs = "Done{E.Rs.mask(%s, [%d])}" % (sm, x)
            for i in range(3):
                I = "%dn" % i
                for v in range(4):
                    out.append("def rsp.s4%s_%d_%d_%d() -> {D.Rs.decode(%s, D.Rs.inject(%s, %s, %d), %s) == %s : %s}:\n  {==}\n" % (kind, x, i, v, sm, cw, I, v, eras(I), rhs, R))
                out.append("def rsp.s4%s_%d_%d(v: U32) -> {D.Rs.decode(%s, D.Rs.inject(%s, %s, M.Gfm.elt(%s, v)), %s) == %s : %s}:\n  match v:" % (kind, x, i, sm, cw, I, f, eras(I), rhs, R))
                for v in range(4):
                    out.append("    case %s:\n      %%rsp.l4_%d(%s) : {D.Rs.decode(%s, D.Rs.inject(%s, %s, _), %s) == %s : %s}\n      rsp.s4%s_%d_%d_%d()" % (pb(v), v, bargs, sm, cw, I, eras(I), rhs, R, kind, x, i, v))
                out.append("")

            def goal(I):
                return "{D.Rs.decode(%s, D.Rs.inject(%s, %s, M.Gfm.elt(%s, v)), %s) == %s : %s}" % (sm, cw, I, f, eras(I), rhs, R)
            if kind == "e":
                out.append("def rsp.s4e_%d(i: Nat, v: U32) -> %s:\n  match i:" % (x, goal("i")))
                for i in range(3):
                    out.append("    case %dn:\n      rsp.s4e_%d_%d(v)" % (i, x, i))
                cwl = ", ".join(map(str, small4_codeword(x)))
                ev = "M.Gfm.elt(%s, v)" % f
                out.append("    case 3n+k:")
                out.append("      %%rsp.cw4_%d() : {D.Rs.decode(%s, D.Rs.inject(_, 3n+k, %s), Nil{}) == %s : %s}" % (x, sm, ev, rhs, R))
                out.append("      %%rsp.inj3(%s, k, %s) : {D.Rs.decode(%s, _, Nil{}) == %s : %s}" % (cwl, ev, sm, rhs, R))
                out.append("      rsp.s4e_%d_far()\n" % x)
            else:
                out.append("def rsp.s4r_%d(i: Nat, v: U32, hi: {Nat.is_lt(i, 3n) == True{} : Bool}) -> %s:\n  match i:" % (x, goal("i")))
                for i in range(3):
                    out.append("    case %dn:\n      rsp.s4r_%d_%d(v)" % (i, x, i))
                out.append("    case 3n:\n      Empty.absurd(%s, rsp.ft(hi))" % goal("3n"))
                out.append("    case 4n+k:\n      Empty.absurd(%s, rsp.ft(hi))\n" % goal("4n+k"))
        cwa = "E.Rs.codeword(%s, E.Rs.mask(%s, [a]))" % (sm, sm)
        rhsa = "Done{E.Rs.mask(%s, [a])}" % sm
        hip = ", hi: {Nat.is_lt(i, 3n) == True{} : Bool}" if kind == "r" else ""
        hia = ", hi" if kind == "r" else ""
        out.append("def rsp.s4%s_c(a: U32, +i: Nat, +v: U32%s) -> {D.Rs.decode(%s, D.Rs.inject(%s, i, M.Gfm.elt(%s, v)), %s) == %s : %s}:\n  match a:" % (kind, hip, sm, cwa, f, eras("i"), rhsa, R))
        for x in range(4):
            out.append("    case %s:\n      %%rsp.lm4_%d(%s) : {D.Rs.decode(%s, D.Rs.inject(E.Rs.codeword(%s, _), i, M.Gfm.elt(%s, v)), %s) == Done{E.Rs.mask(%s, [%d])} : %s}\n      rsp.s4%s_%d(i, v%s)" % (pa(x), x, cargs, sm, sm, f, eras("i"), sm, x, R, kind, x, hia))
        out.append("")
        law = "small4_error(a, i, v)" if kind == "e" else "small4_erasure(a, i, v, hi)"
        out.append("def Laws.%s:" % law)
        out.append("  %%rsp.cwmask4([a]) : {D.Rs.decode(%s, D.Rs.inject(_, i, v), %s) == %s : %s}" % (sm, eras("i"), rhsa, R))
        out.append("  %%rsp.decv4(%s, i, v, %s) : {_ == %s : %s}" % (cwa, eras("i"), rhsa, R))
        out.append("  rsp.s4%s_c(a, i, v%s)\n" % (kind, hia))
    return "\n".join(out)


def gen_inv():
    """a a^-1 = 1 for each nonzero element: the element is first read
    modulo 2^m (rsp.mi_F), then its bits tried and the unknown high ones
    rewritten away, each product computed on literals; 0 is excluded by
    the law's hypothesis."""
    out = []
    for name, f, n in (("gf8", F8, 3), ("gf16", "M.Gfm.gf16()", 4)):
        eid = "rsp.eid_%s" % name[2:]
        hs = ", ".join("+a%d: Bool" % i for i in range(n, 32))
        hargs = ", ".join("a%d" % i for i in range(n, 32))
        ea = "M.Gfm.elt(%s, a)" % f
        out.append("def rsp.mi_%s(+a: U32) -> {M.Gfm.mul(%s, %s, A.RsGf.inv(%s, %s)) == M.Gfm.mul(%s, a, A.RsGf.inv(%s, a)) : U32}:" % (name, f, ea, f, ea, f, f))
        out.append("  %%Equal.sym(U32, M.Gfm.elt(%s, %s), %s, %s(a)) : {M.gfm.mul.raw(%s, _, M.Gfm.elt(%s, A.rsgf.inv.go(Nat.sub(M.Gfm.m(%s), 1n), %s, _, 1))) == M.Gfm.mul(%s, a, A.RsGf.inv(%s, a)) : U32}" % (f, ea, ea, eid, f, f, f, f, f, f))
        out.append("  {==}\n")
        for v in range(1, 1 << n):
            out.append("def rsp.l%s_%d(%s) -> {%d == M.Gfm.elt(%s, %s) : U32}:\n  {==}\n" % (name, v, hs, v, f, word(low("a", v, n))))
            out.append("def rsp.iv%s_%d() -> {M.Gfm.mul(%s, %d, A.RsGf.inv(%s, %d)) == 1 : U32}:\n  {==}\n" % (name, v, f, v, f, v))
        out.append("def rsp.inv%s_c(a: U32, nz: {U32.is_eq(%s, 0) == False{} : Bool}) -> {M.Gfm.mul(%s, %s, A.RsGf.inv(%s, %s)) == 1 : U32}:\n  match a:" % (name, ea, f, ea, f, ea))
        for v in range(1 << n):
            p = word(low("a", v, n))
            ep = "M.Gfm.elt(%s, %s)" % (f, p)
            if v == 0:
                out.append("    case %s:\n      Empty.absurd({M.Gfm.mul(%s, %s, A.RsGf.inv(%s, %s)) == 1 : U32}, rsp.ft(Equal.sym(Bool, True{}, False{}, nz)))" % (p, f, ep, f, ep))
            else:
                out.append("    case %s:\n      %%rsp.l%s_%d(%s) : {M.Gfm.mul(%s, _, A.RsGf.inv(%s, _)) == 1 : U32}\n      rsp.iv%s_%d()" % (p, name, v, hargs, f, f, name, v))
        out.append("")
        out.append("def Laws.inv_%s(a, nz):\n  %%rsp.mi_%s(a) : {_ == 1 : U32}\n  rsp.inv%s_c(a, nz)\n" % (name, name, name))
    return "\n".join(out)


SECTIONS = {"bits": gen_bits, "dist8": gen_dist8, "lin8": gen_lin8, "basis8": gen_basis8, "small4": gen_small4, "inv": gen_inv}


def main():
    path = os.path.join(HERE, "PROOF.bend")
    text = open(path).read()
    for name, fn in SECTIONS.items():
        begin = "# BEGIN GENERATED by gen/proof.py: %s\n" % name
        end = "# END GENERATED: %s\n" % name
        i, j = text.find(begin), text.find(end)
        if i < 0 or j < 0:
            raise SystemExit("PROOF.bend has no section " + name)
        text = text[:i + len(begin)] + fn().rstrip("\n") + "\n" + text[j:]
    with open(path, "w", newline="\n") as f:
        f.write(text)


main()
